const sealScenarioActionPolicies = `-- name: SealScenarioActionPolicies :execrows
UPDATE scenario_test_action_policies SET sealed_at=$1::timestamptz,
 sealed_snapshot=CASE WHEN app_id=$2::text::uuid THEN $3::jsonb ELSE NULL END
WHERE account_id=$4::text::uuid AND run_id=$5::text AND sealed_at IS NULL
`

type SealScenarioActionPoliciesParams struct {
	SealedAt    pgtype.Timestamptz
	AnchorAppID string
	Snapshot    []byte
	AccountID   string
	RunID       string
}

func (q *Queries) SealScenarioActionPolicies(ctx context.Context, db DBTX, arg SealScenarioActionPoliciesParams) (int64, error) {
	result, err := db.Exec(ctx, sealScenarioActionPolicies,
		arg.SealedAt,
		arg.AnchorAppID,
		arg.Snapshot,
		arg.AccountID,
		arg.RunID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
